  function earliest(c,from,to){const best=new Map();const startPassed=!c.checkpoint||from===2;let queue=[[0,from,startPassed]];while(queue.length){queue.sort((a,b)=>a[0]-b[0]);const [time,node,passed]=queue.shift(),key=node+':'+passed;if(best.has(key))continue;best.set(key,time);if(node===to&&passed)return time;for(const [a,b,length] of edges){if(node!==a&&node!==b)continue;const next=node===a?b:a;let depart=time;if(c.gate&&((a===1&&b===2)||(a===2&&b===1))&&depart>=1&&depart<5)depart=5;queue.push([depart+length,next,passed||next===2]);}}return Infinity;}
