  function judge(c,mode,id,known,pinned){if(!profiles.some(p=>p.id===id))return {status:'invalid',text:'Chọn một hồ sơ trước.'};if(!c.required.every(k=>known.includes(k)&&pinned.includes(k)))return {status:'insufficient',text:'Chưa đủ nguồn đã kiếm và ghim. Chưa chấm đúng hoặc sai danh tính.'};const solution=candidates(c,mode,known);if(solution.length!==1)return {status:'ambiguous',text:'Nguồn chưa cho đúng một nghiệm. Không chốt theo đáp án kín.'};return solution[0]===id?{status:'solved',text:'Lập luận khớp đủ nguồn. Đây là hồ sơ bị máy ghép thừa, không phải đánh giá con người.'}:{status:'retry',text:'Hồ sơ này chưa giải thích được toàn bộ nguồn. Thử lại trên bảng giả thuyết, không mất lượt.'};}
  function createProgress(){return {photo:{unlocked:0,completed:[]},route:{unlocked:0,completed:[]}};}
  function complete(progress,mode,index,result){if(!['photo','route'].includes(mode)||!Number.isInteger(index)||index<0||index>2)return false;const p=progress[mode];if(result.status!=='solved'||index>p.unlocked)return false;if(!p.completed.includes(index))p.completed.push(index);p.unlocked=Math.max(p.unlocked,Math.min(index+1,2));return true;}
